-- T021 — the audit entry's target label (specs/002-identity/data-model.md §2 "audit_logs", §5
-- rule 29, §8; ERD §12 `audit_logs`, §15 rule 29; FR-180; ADR 0021 D2). Generated by `prisma
-- migrate diff --from-config-datasource --to-schema prisma/schema --script` against a database
-- holding every migration before it, then extended by hand for the check the schema language
-- cannot say. A forward migration before the first administrative action is written: the table
-- holds no row (the seed writes none), so NOT NULL needs no default. The writer that renders the
-- label lands in the same batch, B4, as the conflict review of 2026-10-18 decided; the Phase 0
-- probes that insert audit rows gain the column with it. The append-only privileges of
-- `20261007000100_roles_and_privileges` and rule 21 stand: the label is written once and never
-- rewritten.

-- AlterTable
ALTER TABLE "audit_logs" ADD COLUMN     "target_label" TEXT NOT NULL;

-- Hand-written: what the schema language cannot say (data-model.md §5, ERD §15).
-- Rule 29: the label is at most 200 characters (`AUDIT_LABEL_MAX_LENGTH` of packages/contracts,
-- which the writer reads too); NOT NULL is the generated part above. An empty label is the
-- writer's refusal (contracts/kernel.md "The audit writer").
ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_target_label_check"
  CHECK (char_length("target_label") <= 200);
